// ============ Express 4.x 线性中间件链 ============
const express = require('express');
const app = express();

// 应用级中间件：必须调 next()，不调则短路
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {  // Express 没有后置逻辑，需监听 finish
    console.log(`${req.method} ${req.url} - ${Date.now() - start}ms`);
  });
  next();
});

app.get('/user/:id', (req, res) => {
  res.send(`User ${req.params.id}`);
});

// 错误中间件：必须 4 个参数，Express 按参数个数区分
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(err.status || 500).json({ message: err.message });
});

// ============ Koa 2.x 洋葱模型 ============
const Koa = require('koa');
const koa = new Koa();

// 计时中间件：await next() 前后天然对称
koa.use(async (ctx, next) => {
  const start = Date.now();
  await next();  // 等所有下游中间件完成
  const ms = Date.now() - start;
  ctx.set('X-Response-Time', `${ms}ms`);
  console.log(`${ctx.method} ${ctx.url} - ${ms}ms`);
});

koa.use(async (ctx, next) => {
  await next();
  console.log('后置逻辑：ctx.status =', ctx.status, 'ctx.body =', ctx.body);
});

koa.use(async (ctx) => {
  ctx.body = { user: 'demo' };
});

// ============ 手写 compose（洋葱模型核心） ============
function compose(middlewares) {
  if (!Array.isArray(middlewares)) {
    throw new TypeError('middlewares must be an array');
  }
  for (const fn of middlewares) {
    if (typeof fn !== 'function') {
      throw new TypeError('each middleware must be a function');
    }
  }

  return function (ctx) {
    let index = -1;  // 记录当前执行位置，防止 next 多次调用
    function dispatch(i) {
      if (i <= index) {
        // next() 被多次调用：第二次 dispatch 的 i 不会大于上次的 index
        return Promise.reject(new Error('next() called multiple times'));
      }
      index = i;
      const fn = middlewares[i];
      if (!fn) return Promise.resolve();  // 所有中间件执行完毕
      try {
        // 把 dispatch(i+1) 作为 next 传入，形成递归 Promise 链
        return Promise.resolve(fn(ctx, dispatch.bind(null, i + 1)));
      } catch (err) {
        // 同步异常包装为 rejected Promise
        return Promise.reject(err);
      }
    }
    return dispatch(0);
  };
}

// 使用 compose 手动构建洋葱
const middlewares = [
  async (ctx, next) => { ctx.state.trace = ['m1-start']; await next(); ctx.state.trace.push('m1-end'); },
  async (ctx, next) => { ctx.state.trace.push('m2-start'); await next(); ctx.state.trace.push('m2-end'); },
  async (ctx) => { ctx.state.trace.push('m3'); ctx.body = { trace: ctx.state.trace }; },
];
const handler = compose(middlewares);
